ll, "status": "draft", "id": "9a1df20a-5b12-57d3-9bad-814ccf81e5a3"}, {"title": "明廷赈济顺天河间保定饥荒", "description": "顺天、河间和保定发生饥荒，朝廷下令赈济。", "start_year": 1407, "end_year": 1407, "time_original": "永乐五年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8446398d-430b-5c14-84a7-76e83877c087"}, {"title": "张辅擒获黎季犛和黎苍并送京", "description": "张辅俘获黎季犛、黎苍，将他们送往京师。本纪至此记安南平定。", "start_year": 1407, "end_year": 1407, "time_original": "永乐五年五月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c583647-9795-5644-be9b-475867f372a6"}, {"title": "明廷查办河南瞒报饥荒的官员", "description": "河南发生饥荒，朝廷逮捕查办隐瞒灾情的主管官员，并命都察院处罚不按实情报告灾害的官员。", "start_year": 1407, "end_year": 1407, "time_original": "永乐五年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9becc390-5420-5825-a901-7610d76263ba"}, {"title": "明廷诏告安南平定并设置交阯布政司", "description": "朝廷向天下诏告安南平定，并设置交阯布政司。", "start_year": 1407, "end_year": 1407, "time_original": "永乐五年六月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "634ff76e-c9ac-546c-9d0b-af56b7972499"}, {"title": "山阳人丁珏告发同乡后获授官", "description": "山阳人丁珏告发同乡诽谤，随后获任刑科给事中。", "start_year": 1407, "end_year": 1407, "time_original": "永乐五年六月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "91d0fcbe-4c46-58e6-887f-0b2fe2cd3693"}, {"title": "明廷赦免永乐二年六月以后获罪离任者", "description": "朝廷下诏，从永乐二