null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "14dacdb2-8887-5737-bd0a-2b2167799be4"}, {"title": "京师夜间地震", "description": "本纪记京师于五月壬戌夜间发生地震。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年五月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c78486de-c81b-522d-8bcd-7fc8d63b9899"}, {"title": "明廷令北京停办不急事务并给归来流民免役", "description": "朝廷为缓解百姓生活困难，下诏停止北京诸官署不紧急的事务和采买。流民归来者免役三年。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年六月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "98026049-be6c-5d54-a728-77f98411510b"}, {"title": "张辅和沐晟率军返回", "description": "本纪记张辅、沐晟在六月丁亥返回。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年六月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e367c47f-7667-5a3a-96a4-573561dccdd4"}, {"title": "明廷按交阯战功封赏张辅等人", "description": "朝廷评定平交阯的战功，封张辅为英国公、沐晟为黔国公、王友为清远侯、都督佥事柳升为安远伯，其余人员依功受赏。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年七月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10a47f09-85cb-59df-835a-3800748a5660"}, {"title": "本纪记简定起兵，沐晟领兵出讨", "description": "交阯简定起兵反明，朝廷任命沐晟为征夷将军，率兵征讨。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年八月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2555413c-9c53-5841-9d60-6ec4126ad1a8"}, {"title": "刘儁再次出征", "description": "永乐6年（年号对照1408年）八月，刘儁再次出征。", "start_year": 1408, "end_year": 1408, "time_original": "永乐6年（年号对照1408年）八月；公元年核为1408年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "59b5ec05-5dd5-5dbb-8318-040773d988c0"}, {"title": "明廷命刑部处理积压案件", "description": "朝廷命刑部处理长期未结的案件。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年九月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2de96eb9-4e71-5bd0-baae-0f3319952278"}, {"title": "郑和再次出使西洋", "description": "本纪记郑和于九月癸亥再次出使西洋。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年九月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9504c120-a0d6-5e50-a626-15a5f22c6f1e"}, {"title": "明廷复核囚案", "description": "朝廷于十一月丁巳复核囚案。", "start_year": 1408, "end_year": 1408, "time_original": "永乐六年十一月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "92a9b43d-ce9c-56d5-808f-82dff3d6b99c"}, {"title": "沐晟在生厥江作战失利", "description": "沐晟率军与简定部在生厥江交战，明军战败，刘儁、都督佥事吕毅及参政刘昱因此身亡。", "start_year": 1409, "end_year": 1409, "time_original": "永乐六年十二月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4e99dd0a-d386-580a-9b29-74b8730fcdac"}, {"title": "刘儁在作战中身亡", "description": "永乐6年（年号对照1408年）十二月，刘儁在作战中身亡。原历日期只能确定在公元1408年至1409年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "永乐6年（年号对照1408年）十二月；发生于公元1408至1409年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "326b67ce-992f-52ef-8f55-b96c6a792053"}, {"title": "柳升等率水军分路在沿海捕倭", "description": "这个月，柳升、陈瑄和李彬等率水军沿海分路追捕倭寇。 按原历纪年，事情发生在公元1408至1409年之间。", "start_year": null, "end_year": null, "time_original": "永乐六年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1071b9c-40c1-549b-9f33-f2afd9a42cdd"}, {"title": "本纪记鬼力赤被杀，本雅失里继为可汗", "description": "本纪在本年记鬼力赤被部下所杀，本雅失里被推立为可汗。 按原历纪年，事情发生在公元1408至1409年之间。", "start_year": null, "end_year": null, "time_original": "永乐六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1215c669-6043-560e-9ccf-dd8593a8db11"}, {"title": "浡泥国王来朝", "description": "本纪记载，浡泥国王在这一年到明朝入朝。 按原历纪年，事情发生在公元1408至1409年之间。", "start_year": null, "end_year": null, "time_original": "永乐六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23460894-508a-571f-b170-c50ae3275040"}, {"title": "瓦剌等地遣使入贡", "description": "本纪记载，瓦剌、占城、于阗、暹罗、撒马儿罕、榜葛剌、冯嘉施兰、日本、爪哇和琉球中山、山南在这一年遣使入贡。 按原历纪年，事情发生在公元1408至1409年之间。", "start_year": null, "end_year": null, "time_original": "永乐六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "136f9875-dc7a-5f45-9294-98d2c1d2a2e9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

